/** The pull request tools of a GitHub MCP server that set the body: `create_pull_request` and `update_pull_request`. */
export const PR_WRITE_TOOL = /^mcp__.+__(?:create|update)_pull_request$/;

/** True when `body` ends with `line`, with the white space at its end ignored. */
export const endsWithLine = (body: string, line: string): boolean =>
  body.trimEnd().endsWith(line.trim());

/** The text of a `gh pr view --json body` answer, or `undefined` when it holds no body. */
export const bodyOf = (stdout: string): string | undefined => {
  try {
    const body: unknown = Reflect.get(JSON.parse(stdout) as object, "body");
    return typeof body === "string" ? body : undefined;
  } catch {
    return undefined;
  }
};

/** The note for a body without the line, or `undefined` when the body has it. */
export const missingNote = (body: string, line: string): string | undefined =>
  endsWithLine(body, line) ? undefined : PR_MISSING({ line });

/** The URL on the last line of the output of `gh pr create`, which names the new pull request. */
export const urlOf = (text: string): string | undefined => {
  const last = text.trim().split("\n").at(-1)?.trim() ?? "";
  try {
    const url = new URL(last);
    return url.protocol === "https:" || url.protocol === "http:"
      ? last
      : undefined;
  } catch {
    return undefined;
  }
};
